              "한국에서 가입·결제·이용이 모두 정상 동작합니다. 다만 ChatGPT 와 달리 음성 모드와 자체 이미지 생성은 약하므로, 멀티미디어 생성보다는 텍스트·코드 중심 작업에 집중적으로 사용됩니다.",
